// 翻译映射
export const translations: Record<string, Translation> = {
  'zh-CN': zhCN,
  'zh-TW': zhTW,
  'en-US': enUS,
  'ja-JP': jaJP,
  'ko-KR': koKR,
  'es-ES': esES,
  'fr-FR': frFR,
  'de-DE': deDE,
  'ru-RU': ruRU,
}

// 获取翻译函数
export const getTranslation = (languageCode: string): Translation => {
  return translations[languageCode] || translations['zh-CN']
}
